def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(
        {v for row in grid for v in row},
        key=lambda v: sum(row.count(v) for row in grid)
    )

    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((color, r, c, dc))

    if not pairs:
        return out

    # The ray is marked by the diagonal pair, typically in color 7 or 4.
    target_color = next((color for color in (7, 4)
                         if any(p[0] == color for p in pairs)),
                        pairs[0][0])
    _, r, c, dc = next(p for p in pairs if p[0] == target_color)

    r += 2
    c += 2 * dc
    while 0 <= r < h and 0 <= c < w:
        out[r][c] = target_color
        r += 1
        c += dc

    return out
