def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Each diagonal pair defines a ray. Extend downwards; if that end is
    # immediately blocked, extend from the other end in the opposite direction.
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((r, c, dc, color))

    for r, c, dc, color in pairs:
        # Forward ray, continuing down along the pair's diagonal.
        rr, cc = r + 2, c + 2 * dc
        added = False
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == background:
                out[rr][cc] = color
                added = True
            elif grid[rr][cc] != color:
                break
            rr += 1
            cc += dc

        # If the forward end is blocked right away, use the opposite ray.
        nr, nc = r + 2, c + 2 * dc
        blocked_immediately = (
            0 <= nr < h and 0 <= nc < w and grid[nr][nc] != background
            and grid[nr][nc] != color
        )
        if blocked_immediately:
            rr, cc = r - 1, c - dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == background:
                    out[rr][cc] = color
                elif grid[rr][cc] != color:
                    break
                rr -= 1
                cc -= dc

    return out
